// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue, uniqueSuffix } from '@skyramp/skyramp';
import { createLink, pinLink, deleteLink, getLinkPin } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    const linkName = uniqueSuffix("testbot pin rejections");
    const linkUrl = uniqueSuffix("https://example.com/testbot-pin-rejections");

    const linksPostResponse = await createLink(
        client,
        URL_localhost,
        headers,
        linkName,
        linkUrl
    );

    expect(getResponseValue(linksPostResponse, "response.name"), 'name').toBe(linkName);
    expect(getResponseValue(linksPostResponse, "response.url"), 'url').toBe(linkUrl);
    expect(getResponseValue(linksPostResponse, "response.id"), 'id').toBeGreaterThan(0);

    const linkId = getResponseValue(linksPostResponse, "response.id");

    const linksPinPatchResponse = await pinLink(client, URL_localhost, headers, linkId);

    expect(linksPinPatchResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(linksPinPatchResponse, "response.id"), 'id').toBe(linkId);
    expect(getResponseValue(linksPinPatchResponse, "response.name"), 'name').toBe(linkName);
    expect(getResponseValue(linksPinPatchResponse, "response.pinnedBy").length, 'pinnedBy length').toBe(1);
    expect(getResponseValue(linksPinPatchResponse, "response.pinnedBy.0.id"), 'pinnedBy.0.id').toBeGreaterThan(0);
    expect(getResponseValue(linksPinPatchResponse, "response.pinnedBy.1"), 'pinnedBy.1').toBeNull();

    const pinPatchResponse = await pinLink(client, URL_localhost, headers, 999000111, 404);

    expect(getResponseValue(pinPatchResponse, "response"), 'response').toBe("Link not found.");
    expect(getResponseValue(pinPatchResponse, "response.id"), 'no link payload').toBeNull();

    const abcPinPatchResponse = await pinLink(client, URL_localhost, headers, "abc", 400);

    expect(abcPinPatchResponse.statusCode, 'status code').toBe(400);
    expect(getResponseValue(abcPinPatchResponse, "response"), 'response').toBe("Invalid link ID.");
    expect(getResponseValue(abcPinPatchResponse, "response.id"), 'no link payload').toBeNull();

    const linksPinGetResponse = await getLinkPin(client, URL_localhost, headers, linkId);

    expect(getResponseValue(linksPinGetResponse, "response"), 'response').toBe("Method not allowed.");
    expect(getResponseValue(linksPinGetResponse, "response.id"), 'no link payload').toBeNull();

    const linksLinksDeleteResponse = await deleteLink(client, URL_localhost, headers, linkId);

    expect(getResponseValue(linksLinksDeleteResponse, "response.id"), 'id').toBe(linkId);
    expect(getResponseValue(linksLinksDeleteResponse, "response.name"), 'name').toBe(linkName);
});
